{
  "summary": "The first action is to construct a SQL query to join the journeys and services tables, filter for regular service and operated trips, and calculate the seat-time occupancy ratio.",
  "actions": [
    {
      "tool": "construct_table",
      "name": "query.json",
      "dataset": "mobility-bay-16",
      "sql": "SELECT SUM(journeys.occupied * journeys.minutes) / SUM(journeys.capacity * journeys.minutes) AS occupancy_ratio FROM journeys JOIN services ON journeys.line_id = services.line_id WHERE services.scope = 'regular' AND journeys.state = 'operated'"
    }
  ],
  "done": false
}
